#!/bin/sh
# Backfill the synthetic history (OpenMetrics, generated by scripts/generate_telemetry.py) into an empty TSDB, then
# start Prometheus. Storage is a tmpfs, so this runs on every container start.
set -eu
if [ -f /seed/seed.om ]; then
  promtool tsdb create-blocks-from openmetrics /seed/seed.om /prometheus >/dev/null
fi
exec /bin/prometheus \
  --config.file=/etc/prometheus/prometheus.yml \
  --storage.tsdb.path=/prometheus \
  --storage.tsdb.retention.time=3650d \
  --web.listen-address=:9090
